// What: Generates lib/src/third_party/automerge.g.dart, the `@Native`
//   dart:ffi bindings of the automerge-c functions this package calls.
// Why: docs/decisions/007-crdt-automerge.md (PNT-A0013-02) requires
//   ffigen-generated bindings instead of hand-written dart:ffi lookups.
// Coupled to: third_party/automerge-c/include/automerge-c/automerge.h (input,
//   regenerated by tool/generate_header.dart), hook/build.dart (its asset name
//   must equal [_assetId]), lib/src/ (the only callers of the bindings).
//
// Usage, from the package root: dart run tool/ffigen.dart

import 'dart:io';

import 'package:ffigen/ffigen.dart';

/// Asset id of the native library; the build hook registers the library
/// under this id (hook/build.dart builds it with the asset name
/// `src/third_party/automerge.g.dart`).
const _assetId = 'package:automerge_dart/src/third_party/automerge.g.dart';

/// The C functions the Dart API in lib/src/ calls. Keep in step with it:
/// add a name here before calling a new function, then regenerate.
const _functions = {
  // Results and their items.
  'AMresultError',
  'AMresultFree',
  'AMresultItem',
  'AMresultItems',
  'AMresultStatus',
  'AMitemsNext',
  'AMitemObjId',
  'AMitemToActorId',
  'AMitemToBool',
  'AMitemToBytes',
  'AMitemToChangeHash',
  'AMitemToDoc',
  'AMitemToF64',
  'AMitemToInt',
  'AMitemToStr',
  'AMitemToSyncMessage',
  'AMitemToSyncState',
  'AMitemValType',
  // Actor and object ids.
  'AMactorIdFromStr',
  'AMactorIdStr',
  'AMobjIdActorId',
  'AMobjIdCounter',
  // Documents.
  'AMcommit',
  'AMcreate',
  'AMfork',
  'AMgetActorId',
  'AMgetHeads',
  'AMload',
  'AMmerge',
  'AMsave',
  'AMsetActorId',
  // Maps and objects.
  'AMkeys',
  'AMmapDelete',
  'AMmapGet',
  'AMmapPutBool',
  'AMmapPutBytes',
  'AMmapPutF64',
  'AMmapPutInt',
  'AMmapPutNull',
  'AMmapPutObject',
  'AMmapPutStr',
  'AMobjObjType',
  // Sync.
  'AMgenerateSyncMessage',
  'AMreceiveSyncMessage',
  'AMsyncMessageDecode',
  'AMsyncMessageEncode',
  'AMsyncStateDecode',
  'AMsyncStateEncode',
  'AMsyncStateInit',
};

/// Functions that only read or convert an existing result or item: they are
/// short and never call back into Dart, so they are safe as leaf calls.
/// Document operations (load, save, merge, sync) can run long and stay
/// non-leaf so they do not hold up the VM's safepoints.
bool _isLeaf(String name) =>
    name.startsWith('AMresult') ||
    name.startsWith('AMitem') ||
    name.startsWith('AMobjId') ||
    name == 'AMactorIdStr';

/// Structs passed or returned by value, which ffigen needs as full layouts.
/// Other structs are referenced through pointers and are generated as
/// opaque types automatically.
const _structs = {'AMbyteSpan', 'AMitems'};

Future<void> main() async {
  final packageRoot = Platform.script.resolve('../');
  final header = packageRoot.resolve(
    'third_party/automerge-c/include/automerge-c/automerge.h',
  );

  await FfiGenerator(
    input: Input(entryPoints: [header]),
    visitors: [
      Visitor(
        func: (node) {
          if (_functions.contains(node.originalName)) {
            node
              ..isIncluded = true
              ..isLeaf = _isLeaf(node.originalName)
              // The NativeFinalizer that frees results needs its address.
              ..exposeSymbolAddress = node.originalName == 'AMresultFree';
          }
        },
        struct: (node) {
          if (_structs.contains(node.originalName)) node.isIncluded = true;
        },
        // The enum ABI warning is accepted: every target in
        // rust-toolchain.toml is an Apple Clang target, where these enums
        // are 32-bit ints, which is the size ffigen assumes.
        enumClass: (node) => node.silenceWarning = true,
      ),
    ],
    output: Output(
      dart: DartOutput(
        path: packageRoot.resolve('lib/src/third_party/automerge.g.dart'),
      ),
      style: const NativeExternalBindings(assetId: _assetId),
      preamble: '''
// Bindings for third_party/automerge-c/include/automerge-c/automerge.h.
//
// Copyright (c) 2019-2021 the Automerge contributors
// Licensed under the MIT License; see third_party/automerge-c/LICENSE.
//
// Generated by package:ffigen. Do not edit manually.
// To regenerate: dart run tool/ffigen.dart

// ignore_for_file: type=lint, unused_import, unused_element
''',
    ),
  ).generate();
}
